package tools

import (
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"sync"

	"github.com/notshekhar/pi/internal/ai"
	"github.com/notshekhar/pi/internal/ai/jsonschema"
)

// loop's tool definitions — the description and JSON schema of every tool,
// exactly as loop's model sees them. Generated by scripts/sync-loop/export.ts.
//
// pi's tools take their definitions from here rather than restating them: a
// description is the model's only guidance for a tool, so a paraphrase is a
// different tool. One file, read by both agents, cannot drift.
//
//go:embed defs/loop-tools.json
var loopDefsJSON []byte

// Def is one tool as the model is told about it.
type Def struct {
	Description string             `json:"description"`
	Schema      *jsonschema.Schema `json:"schema"`
}

var loadDefs = sync.OnceValue(func() map[string]Def {
	defs := map[string]Def{}
	if err := json.Unmarshal(loopDefsJSON, &defs); err != nil {
		panic(fmt.Sprintf("tools: defs/loop-tools.json is not valid: %v", err))
	}
	return defs
})

// LoopDef returns loop's definition of a tool. A missing name is a build
// mistake — the sync script and the Go tool list disagree — so it panics
// rather than shipping a tool with no description.
func LoopDef(name string) Def {
	def, ok := loadDefs()[name]
	if !ok {
		panic(fmt.Sprintf("tools: no loop definition for %q; re-run scripts/sync-loop/export.ts", name))
	}
	return def
}

// LoopDefNames is every tool loop defines.
func LoopDefNames() []string {
	names := make([]string, 0, len(loadDefs()))
	for name := range loadDefs() {
		names = append(names, name)
	}
	return names
}

// LoopTool builds a tool that carries loop's definition and runs execute.
func LoopTool[T any](name string, execute func(ctx context.Context, args T) (ai.ToolResult, error)) ai.Tool {
	def := LoopDef(name)
	return ai.NewToolWithSchema(name, def.Description, def.Schema, execute)
}
